window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-6dc6a564d6d5312e"]={"versions": [{"id": "FIG-6dc6a564d6d5312e", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Architektur- und Datenflussdiagramm (informelles Sequenz- und Interaktionsdiagramm) zur AUTOSAR Classic Platform (SWS Diagnostic Log and Trace). Das Diagramm veranschaulicht zwei gegenläufige Kommunikationspfade zwischen einer Software-Komponente (SWC) im Application Layer und einem externen Diagnose-/DLT-Client über den DLT-Kommunikationsstack und physikalische Busmedien.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>SWC (Software Component)</strong>: Gelber Block im Application Layer, sendet Log-Nachrichten und empfängt Log-Level-Konfigurationsänderungen.</li>\n<li><strong>RTE (Runtime Environment)</strong>: Horizontale Abstraktionsschicht zwischen SWC und Basic Software.</li>\n<li><strong>DLT (Diagnostic Log and Trace Module)</strong>: Kernmodul (orange), verwaltet intern Log-Level und Kontexte (<code>Level Context / xxx dddd / xxx dddd</code>) und sammelt Log-Meldungen.</li>\n<li><strong>DLT comunication module</strong>: Direkt unterhalb des DLT-Moduls angesiedelter Protokoll- und Kommunikationsadapter (lila Block), empfängt Steuerbefehle und leitet Logs weiter.</li>\n<li><strong>Bussysteme / Netzwerkadapter</strong>: Sammelblock <code>CAN / Flexray / Ethernt / Serial</code> mit Verbindung zum physikalischen Bus/Kabelbaum.</li>\n<li><strong>External Client</strong>: Externes DLT-Werkzeug (symbolisiert als Hardware-/Tester-Box), dient als Senke für Log-Nachrichten und Quelle für Steuerbefehle.</li>\n<li><strong>Schnittstellen & Operationen</strong>:</li>\n<li><code>Dlt_SendLogMessage()</code>: Schnittstelle der SWC zum Absenden von Log-Einträgen.</li>\n<li><code>Dlt_SetLogLevel</code>: Benachrichtigungsschnittstelle zur SWC über geänderte Log-Level.</li>\n<li>Grüne Nachrichtenblöcke: Datenfluss für Log-Nachrichten (Schritte 1 bis 4).</li>\n<li>Hellblaue Nachrichtenblöcke: Datenfluss für Steuerungs- und Konfigurationsnachrichten (Schritte 1 bis 5).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm beschreibt zwei getrennte, nummerierte Abläufe:</p>\n<ol class=\"fig-list\">\n<li><strong>Log-Nachrichten-Ablauf (türkise Ziffernkreise 1–4, grüne Datenpakete)</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>(1)</strong> Die SWC erzeugt eine Log-Nachricht über den Funktionsaufruf <code>Dlt_SendLogMessage()</code>.</li>\n<li><strong>(2)</strong> Die Nachricht passiert die RTE; das DLT-Modul sammelt und puffert die Meldungen (<code>DLT collects messages</code>).</li>\n<li><strong>(3)</strong> Die Log-Nachricht wird über das <code>DLT comunication module</code> an die unterlagerte Netzwerkschicht (<code>CAN / Flexray / Ethernt / Serial</code>) übergeben und über das Netzwerk gesendet.</li>\n<li><strong>(4)</strong> Der externe Client empfängt, sammelt und speichert die Log-Nachrichten (<code>external client collects and stores log messages</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Steuernachrichten-Ablauf zur Log-Level-Konfiguration (pinke Ziffernkreise 1–5, blaue Datenpakete)</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>(1)</strong> Der externe Client initiiert die Konfiguration der Log-Level auf dem DLT-Modul (<code>The external client wants to configure log levels on DLT module</code>).</li>\n<li><strong>(2)</strong> Die Kontrollnachricht wird über das Busnetzwerk übertragen (<code>Control message is send over the network</code>).</li>\n<li><strong>(3)</strong> Das <code>DLT comunication module</code> empfängt die Kontrollnachricht vom Bus.</li>\n<li><strong>(4)</strong> Das DLT-Modul verarbeitet die Nachricht und administriert die zulässigen Log-Level (<code>DLT administrates allowed log levels</code>) anhand der internen Kontext-Tabelle (<code>Level Context</code>).</li>\n<li><strong>(5)</strong> Die SWC wird über die RTE mittels <code>Dlt_SetLogLevel</code> über die Änderung der Log-Level informiert (<code>SWC is informed about changes of log levels</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Konzeptionelle Übersichtsdarstellung zur Verdeutlichung der Entkopplung zwischen externem Client und Anwendungssoftware.</li>\n<li>Die Interaktion zwischen externem Client und ECU läuft ausschließlich über den DLT-Kommunikationskanal; die SWC kommuniziert nicht direkt mit dem Netzwerk.</li>\n<li>Relevanz für Integratoren und Entwickler: Das DLT-Modul filtert und administriert Log-Meldungen basierend auf den konfigurierten Kontexten und Leveln; dynamische Level-Anpassungen durch den Client werden über definierte Callback-/API-Mechanismen an die Applikations-SWC propagiert.</li>\n</ul>"}, {"id": "FIG-a186e6e774edb18a", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Architektur- und Datenflussdiagramm (informelles Sequenz- und Interaktionsdiagramm) zur AUTOSAR Classic Platform (SWS Diagnostic Log and Trace). Das Diagramm veranschaulicht zwei gegenläufige Kommunikationspfade zwischen einer Software-Komponente (SWC) im Application Layer und einem externen Diagnose-/DLT-Client über den DLT-Kommunikationsstack und physikalische Busmedien.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>SWC (Software Component)</strong>: Gelber Block im Application Layer, sendet Log-Nachrichten und empfängt Log-Level-Konfigurationsänderungen.</li>\n<li><strong>RTE (Runtime Environment)</strong>: Horizontale Abstraktionsschicht zwischen SWC und Basic Software.</li>\n<li><strong>DLT (Diagnostic Log and Trace Module)</strong>: Kernmodul (orange), verwaltet intern Log-Level und Kontexte (<code>Level Context / xxx dddd / xxx dddd</code>) und sammelt Log-Meldungen.</li>\n<li><strong>DLT comunication module</strong>: Direkt unterhalb des DLT-Moduls angesiedelter Protokoll- und Kommunikationsadapter (lila Block), empfängt Steuerbefehle und leitet Logs weiter.</li>\n<li><strong>Bussysteme / Netzwerkadapter</strong>: Sammelblock <code>CAN / Flexray / Ethernt / Serial</code> mit Verbindung zum physikalischen Bus/Kabelbaum.</li>\n<li><strong>External Client</strong>: Externes DLT-Werkzeug (symbolisiert als Hardware-/Tester-Box), dient als Senke für Log-Nachrichten und Quelle für Steuerbefehle.</li>\n<li><strong>Schnittstellen & Operationen</strong>:</li>\n<li><code>Dlt_SendLogMessage()</code>: Schnittstelle der SWC zum Absenden von Log-Einträgen.</li>\n<li><code>Dlt_SetLogLevel</code>: Benachrichtigungsschnittstelle zur SWC über geänderte Log-Level.</li>\n<li>Grüne Nachrichtenblöcke: Datenfluss für Log-Nachrichten (Schritte 1 bis 4).</li>\n<li>Hellblaue Nachrichtenblöcke: Datenfluss für Steuerungs- und Konfigurationsnachrichten (Schritte 1 bis 5).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm beschreibt zwei getrennte, nummerierte Abläufe:</p>\n<ol class=\"fig-list\">\n<li><strong>Log-Nachrichten-Ablauf (türkise Ziffernkreise 1–4, grüne Datenpakete)</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>(1)</strong> Die SWC erzeugt eine Log-Nachricht über den Funktionsaufruf <code>Dlt_SendLogMessage()</code>.</li>\n<li><strong>(2)</strong> Die Nachricht passiert die RTE; das DLT-Modul sammelt und puffert die Meldungen (<code>DLT collects messages</code>).</li>\n<li><strong>(3)</strong> Die Log-Nachricht wird über das <code>DLT comunication module</code> an die unterlagerte Netzwerkschicht (<code>CAN / Flexray / Ethernt / Serial</code>) übergeben und über das Netzwerk gesendet.</li>\n<li><strong>(4)</strong> Der externe Client empfängt, sammelt und speichert die Log-Nachrichten (<code>external client collects and stores log messages</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Steuernachrichten-Ablauf zur Log-Level-Konfiguration (pinke Ziffernkreise 1–5, blaue Datenpakete)</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>(1)</strong> Der externe Client initiiert die Konfiguration der Log-Level auf dem DLT-Modul (<code>The external client wants to configure log levels on DLT module</code>).</li>\n<li><strong>(2)</strong> Die Kontrollnachricht wird über das Busnetzwerk übertragen (<code>Control message is send over the network</code>).</li>\n<li><strong>(3)</strong> Das <code>DLT comunication module</code> empfängt die Kontrollnachricht vom Bus.</li>\n<li><strong>(4)</strong> Das DLT-Modul verarbeitet die Nachricht und administriert die zulässigen Log-Level (<code>DLT administrates allowed log levels</code>) anhand der internen Kontext-Tabelle (<code>Level Context</code>).</li>\n<li><strong>(5)</strong> Die SWC wird über die RTE mittels <code>Dlt_SetLogLevel</code> über die Änderung der Log-Level informiert (<code>SWC is informed about changes of log levels</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Konzeptionelle Übersichtsdarstellung zur Verdeutlichung der Entkopplung zwischen externem Client und Anwendungssoftware.</li>\n<li>Die Interaktion zwischen externem Client und ECU läuft ausschließlich über den DLT-Kommunikationskanal; die SWC kommuniziert nicht direkt mit dem Netzwerk.</li>\n<li>Relevanz für Integratoren und Entwickler: Das DLT-Modul filtert und administriert Log-Meldungen basierend auf den konfigurierten Kontexten und Leveln; dynamische Level-Anpassungen durch den Client werden über definierte Callback-/API-Mechanismen an die Applikations-SWC propagiert.</li>\n</ul>"}, {"id": "FIG-924889ea15d4696d", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Architektur- und Datenflussdiagramm (informelles Sequenz- und Interaktionsdiagramm) zur AUTOSAR Classic Platform (SWS Diagnostic Log and Trace). Das Diagramm veranschaulicht zwei gegenläufige Kommunikationspfade zwischen einer Software-Komponente (SWC) im Application Layer und einem externen Diagnose-/DLT-Client über den DLT-Kommunikationsstack und physikalische Busmedien.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>SWC (Software Component)</strong>: Gelber Block im Application Layer, sendet Log-Nachrichten und empfängt Log-Level-Konfigurationsänderungen.</li>\n<li><strong>RTE (Runtime Environment)</strong>: Horizontale Abstraktionsschicht zwischen SWC und Basic Software.</li>\n<li><strong>DLT (Diagnostic Log and Trace Module)</strong>: Kernmodul (orange), verwaltet intern Log-Level und Kontexte (<code>Level Context / xxx dddd / xxx dddd</code>) und sammelt Log-Meldungen.</li>\n<li><strong>DLT comunication module</strong>: Direkt unterhalb des DLT-Moduls angesiedelter Protokoll- und Kommunikationsadapter (lila Block), empfängt Steuerbefehle und leitet Logs weiter.</li>\n<li><strong>Bussysteme / Netzwerkadapter</strong>: Sammelblock <code>CAN / Flexray / Ethernt / Serial</code> mit Verbindung zum physikalischen Bus/Kabelbaum.</li>\n<li><strong>External Client</strong>: Externes DLT-Werkzeug (symbolisiert als Hardware-/Tester-Box), dient als Senke für Log-Nachrichten und Quelle für Steuerbefehle.</li>\n<li><strong>Schnittstellen & Operationen</strong>:</li>\n<li><code>Dlt_SendLogMessage()</code>: Schnittstelle der SWC zum Absenden von Log-Einträgen.</li>\n<li><code>Dlt_SetLogLevel</code>: Benachrichtigungsschnittstelle zur SWC über geänderte Log-Level.</li>\n<li>Grüne Nachrichtenblöcke: Datenfluss für Log-Nachrichten (Schritte 1 bis 4).</li>\n<li>Hellblaue Nachrichtenblöcke: Datenfluss für Steuerungs- und Konfigurationsnachrichten (Schritte 1 bis 5).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm beschreibt zwei getrennte, nummerierte Abläufe:</p>\n<ol class=\"fig-list\">\n<li><strong>Log-Nachrichten-Ablauf (türkise Ziffernkreise 1–4, grüne Datenpakete)</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>(1)</strong> Die SWC erzeugt eine Log-Nachricht über den Funktionsaufruf <code>Dlt_SendLogMessage()</code>.</li>\n<li><strong>(2)</strong> Die Nachricht passiert die RTE; das DLT-Modul sammelt und puffert die Meldungen (<code>DLT collects messages</code>).</li>\n<li><strong>(3)</strong> Die Log-Nachricht wird über das <code>DLT comunication module</code> an die unterlagerte Netzwerkschicht (<code>CAN / Flexray / Ethernt / Serial</code>) übergeben und über das Netzwerk gesendet.</li>\n<li><strong>(4)</strong> Der externe Client empfängt, sammelt und speichert die Log-Nachrichten (<code>external client collects and stores log messages</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Steuernachrichten-Ablauf zur Log-Level-Konfiguration (pinke Ziffernkreise 1–5, blaue Datenpakete)</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>(1)</strong> Der externe Client initiiert die Konfiguration der Log-Level auf dem DLT-Modul (<code>The external client wants to configure log levels on DLT module</code>).</li>\n<li><strong>(2)</strong> Die Kontrollnachricht wird über das Busnetzwerk übertragen (<code>Control message is send over the network</code>).</li>\n<li><strong>(3)</strong> Das <code>DLT comunication module</code> empfängt die Kontrollnachricht vom Bus.</li>\n<li><strong>(4)</strong> Das DLT-Modul verarbeitet die Nachricht und administriert die zulässigen Log-Level (<code>DLT administrates allowed log levels</code>) anhand der internen Kontext-Tabelle (<code>Level Context</code>).</li>\n<li><strong>(5)</strong> Die SWC wird über die RTE mittels <code>Dlt_SetLogLevel</code> über die Änderung der Log-Level informiert (<code>SWC is informed about changes of log levels</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Konzeptionelle Übersichtsdarstellung zur Verdeutlichung der Entkopplung zwischen externem Client und Anwendungssoftware.</li>\n<li>Die Interaktion zwischen externem Client und ECU läuft ausschließlich über den DLT-Kommunikationskanal; die SWC kommuniziert nicht direkt mit dem Netzwerk.</li>\n<li>Relevanz für Integratoren und Entwickler: Das DLT-Modul filtert und administriert Log-Meldungen basierend auf den konfigurierten Kontexten und Leveln; dynamische Level-Anpassungen durch den Client werden über definierte Callback-/API-Mechanismen an die Applikations-SWC propagiert.</li>\n</ul>"}], "trans": [{"from": "FIG-6dc6a564d6d5312e", "to": "FIG-a186e6e774edb18a", "fr": "R4.0.3", "tr": "R4.1.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Die Ziffernbeschriftung „5“ des pinken Schrittzählers oben links bei der SWC-Rückmeldung ist nun als zentrierte Beschriftung in den pinken Kreis eingebettet statt als Textanhang an der Schnittstellenbezeichnung „Dlt_SetLogLevel“.</li>\n<li>Die Ränder des Gesamtdiagramms wurden geringfügig neu beschnitten bzw. skaliert (935x815 auf 925x820 Pixel).</li>\n</ul>"}, {"from": "FIG-a186e6e774edb18a", "to": "FIG-924889ea15d4696d", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
